function inc20ACommencementFlagCheck(formName,flag,incorporationDate){
    var testResult = true;
    if(formName == 'CHG-1' || formName == 'CHG-4' || formName == 'CHG-6' ||formName == 'CHG-8' || formName == 'CHG-9' || formName == 'MGT-14' ||
       formName == 'INC-23' || formName == 'SH-7' || formName == 'RUN' || formName == 'RD-1'|| formName == 'INC-24' || formName == 'INC-4' ||
       formName == 'INC-6' || formName == 'INC-27' || formName == 'INC-12' || formName == 'INC-18'|| formName == 'INC-20' || formName == 'GNL-2' || 
       formName == 'GNL-1' || formName == 'GNL-4' || formName == 'DPT-3' || formName == 'ADT-2'|| formName == 'AOC-4' || formName == 'AOC-4' ||
       formName == 'AOC-4 CFS' || formName == 'AOC-4 NBFC' || formName == 'AOC-4 CFS NBFC' || formName == 'AOC-4 XBRL' || formName == 'MGT-7' || 
       formName == 'AOC-5' || formName == 'MGT-15' || formName == 'MSC-3' || formName == 'MSC-4' || formName == 'MR-2' || formName == 'MR-1' || formName == 'BEN-2' ||
       formName == 'MGT-6' || formName == 'SH-8' || formName == 'SH-9' || formName == 'SH-11' || formName == 'NDH-2' || formName == 'NDH-3' ||
       formName == 'NDH-1' || formName == 'CRA-2' || formName == 'CRA-4' || formName == 'PAS-2' || formName == 'PAS-6' || formName == 'GNL-3' || 
       formName == 'MGT-3' || formName == 'DPT-4' || formName == 'CG-1' || formName == 'INC-22A' || formName == 'Form ADJ' || formName == 'CRL-1' || formName == 'GNL-3' ||
       formName == 'MGT-7A' || formName == 'AOC-4 addendum' || formName == 'AOC-1' || formName == 'AOC-2' || formName == 'e-Directors Report' || 
       formName == 'EAUDITOR Standalone' || formName == 'EAUDITOR Consolidated'){
        if(flag=='Y'){
            testResult=false;
        } else { 
            testResult=true;
        }
    } else {
        switch (formName) {
          case "DIR-12":
                if(flag == "Y"){   
					testResult = dateIncorporationCheck(incorporationDate);
                }   
            break;
          case "DIR-11":
                if(flag == "Y"){   
					testResult = dateIncorporationCheck(incorporationDate);
                }
            break;
          case "PAS-3":
                if(flag == "Y"){   
					testResult = dateIncorporationCheck(incorporationDate);
                }
            break;
          case "INC-28":
                if(flag == "Y"){   
					testResult = dateIncorporationCheck(incorporationDate);
                }
            break;
          case "ADT-1":
                if(flag == "Y"){   
					testResult = dateIncorporationCheck(incorporationDate);
                }
            break;
          case "MSC-1":
                if(flag == "Y"){   
					testResult = dateIncorporationCheck(incorporationDate);
                }
            break;
          case "MSME":
            if(flag == "Y"){   
					testResult = dateIncorporationCheck(incorporationDate);
                }
            break;
          case "INC-4":
            if(flag == "Y"){   
					testResult = dateIncorporationCheck(incorporationDate);
                }
            break;
          case "NDH-4":
                if(new Date(incorporationDate) < new Date('04-19-2022')){
                    if(flag=='Y'){
                        testResult=false;
                    } else { 
                        testResult=true;
                    }
                }
        }
    }
    return testResult;
}


function dateIncorporationCheck(incorporationDate){
    // To set two dates to two variables
    debugger;
                    var date1 = new Date(incorporationDate);
                    var date2 = new Date();
        
                    // To calculate the time difference of two dates
                    var Difference_In_Time = date2.getTime() - date1.getTime();

                    // To calculate the no. of days between two dates
                    var Difference_In_Days = Difference_In_Time / (1000 * 3600 * 24);
                    if(Difference_In_Days < 180){
					   return true;
                    } else {
					   return false;
                    } 
}



















